fn admit_pending_players(
    mut commands: Commands,
    barrier: Option<Res<AlsScenePhysicsReady>>,
    settings: Res<AlsPlayerStartSettings>,
    spatial: SpatialQuery,
    mut random: ResMut<AlsGameModeRandom>,
    all_starts: Query<(Entity, Option<&crate::als::player_start::AlsPlayerStartProbe>), With<AlsPlayerStart>>,
    starts: Query<(Entity, &AlsPlayerStart, &AlsPlayerStartReady)>,
    pending: Query<(Entity, &AlsPlayerAdmission, Option<&AlsPlayerAdmissionComplete>), With<AlsPlayerAdmissionPending>>,
    mut characters: Query<(Option<&mut crate::als::input::AlsInputCommand>,
        Option<&mut crate::als::transition::AlsStateRequest>, &Transform,
        Option<&mut crate::als::motion::AlsViewYaw>, Option<&mut crate::als::view::AlsViewPitch>),
        With<crate::als::character::AlsCharacter>>,
    assets: Res<AssetServer>,
    mut materials: ResMut<Assets<StandardMaterial>>,
    mut params_assets: ResMut<Assets<AlsMovementParams>>,
    mut config_assets: ResMut<Assets<AlsControlSchemeConfig>>,
) {
    if barrier.as_ref().is_some_and(|barrier| !barrier.ready) {
        return;
    }
    for (request, _, previous) in &pending {
        if let Some(previous) = previous && characters.contains(previous.character) {
            if let Ok((input, mode, transform, yaw, pitch)) = characters.get_mut(previous.character) {
                let forward = transform.forward().as_vec3();
                if let Some(mut yaw) = yaw { yaw.0 = crate::als::orientation::world_forward_to_yaw(forward); }
                if let Some(mut pitch) = pitch { pitch.0 = forward.y.atan2(Vec2::new(forward.x, forward.z).length()); }
                if let Some(mut input) = input {
                    input.jump_pressed = false;
                    input.jump_held = false;
                    input.move_dir = Vec2::ZERO;
                }
                if let Some(mut mode) = mode {
                    mode.locomotion_state = Some(crate::als::state::LocomotionState::Grounded);
                }
            }
            commands.entity(previous.character).insert(avian3d::prelude::LinearVelocity::ZERO);
            commands.entity(request).remove::<AlsPlayerAdmissionPending>();
        }
    }
    let candidates: Vec<AlsPlayerStartCandidate> = starts
        .iter()
        .map(|(entity, start, ready)| AlsPlayerStartCandidate {
            entity,
            tag: start.tag.clone(),
            fit: crate::als::player_start::AlsPlayerSpawnFit {
                transform: ready.transform,
                ground_y: ready.ground_y,
                adjustment: ready.adjustment,
                teleport_adjustment: ready.teleport_adjustment,
                occupancy: ready.occupancy,
            },
        })
        .collect();
    if candidates.is_empty() {
        let preparing = all_starts.iter().any(|(_, probe)| probe.is_none_or(|probe| probe.occupancy.is_some()));
        if !all_starts.is_empty() && !preparing {
            for (request, _, previous) in &pending {
                if previous.is_some_and(|previous| characters.contains(previous.character)) { continue; }
                commands
                    .entity(request)
                    .remove::<AlsPlayerAdmissionPending>();
                commands.entity(request).insert(AlsPlayerAdmissionFailed {
                    reason: "No PlayerStart can fit the default pawn".into(),
                });
                info!("[GAMEMODE][DENY] request={request:?} reason=no_fit -> PASS");
            }
        }
        return;

